const aiFormat=s=>{const src=String(s??'').replace(/\r\n?/g,'\n');const code=[];let x=esc(src).replace(/```([\w-]*)\n?([\s\S]*?)```/g,(_,l,c)=>{const i=code.length;code.push('<pre class="md-code"><code>'+c.trimEnd()+'</code></pre>');return '\n@@CODE'+i+'@@\n'});x=x.replace(/^#{6}\s+(.+)$/gm,'<h6>$1</h6>').replace(/^#{5}\s+(.+)$/gm,'<h5>$1</h5>').replace(/^#{4}\s+(.+)$/gm,'<h4>$1</h4>').replace(/^#{3}\s+(.+)$/gm,'<h3>$1</h3>').replace(/^#{2}\s+(.+)$/gm,'<h2>$1</h2>').replace(/^#{1}\s+(.+)$/gm,'<h1>$1</h1>').replace(/^\s*(?:---+|\*\*\*+|___+)\s*$/gm,'<hr class="md-hr">').replace(/^>\s+(.+)$/gm,'<blockquote>$1</blockquote>').replace(/`([^`\n]+)`/g,'<code class="md-inline">$1</code>').replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,'<a href="$2" target="_blank" rel="noopener noreferrer" onclick="event.stopPropagation();window.open(this.href,\'_blank\');return false">$1</a>').replace(/(^|[\s(])(https?:\/\/[^\s<]+)/g,'$1<a href="$2" target="_blank" rel="noopener noreferrer" onclick="event.stopPropagation();window.open(this.href,\'_blank\');return false">$2</a>').replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/__(.+?)__/g,'<strong>$1</strong>').replace(/(?<!\*)\*([^*\n]+)\*(?!\*)/g,'<em>$1</em>').replace(/(?<!_)_([^_\n]+)_(?!_)/g,'<em>$1</em>');const lines=x.split('\n'),out=[];let i=0;while(i<lines.length){const line=lines[i];if(/^\s*\|/.test(line)&&i+1<lines.length&&/^\s*\|?\s*:?-{3,}:?\s*(\|\s*:?-{3,}:?\s*)+\|?\s*$/.test(lines[i+1])){const parse=r=>r.trim().replace(/^\|/,'').replace(/\|$/,'').split('|').map(c=>c.trim());const h=parse(line);i+=2;const rows=[];while(i<lines.length&&/^\s*\|/.test(lines[i])){rows.push(parse(lines[i]));i++}out.push('<div class="md-table-wrap"><table class="md-table"><thead><tr>'+h.map(c=>'<th>'+c+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+h.map((_,j)=>'<td>'+(r[j]||'')+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>');continue}if(/^\s*[-*+]\s+/.test(line)){const a=[];while(i<lines.length&&/^\s*[-*+]\s+/.test(lines[i])){a.push(lines[i].replace(/^\s*[-*+]\s+/,''));i++}out.push('<ul class="md-list">'+a.map(v=>'<li>'+v+'</li>').join('')+'</ul>');continue}if(/^\s*\d+[.)]\s+/.test(line)){const a=[];while(i<lines.length&&/^\s*\d+[.)]\s+/.test(lines[i])){a.push(lines[i].replace(/^\s*\d+[.)]\s+/,''));i++}out.push('<ol class="md-list">'+a.map(v=>'<li>'+v+'</li>').join('')+'</ol>');continue}if(line.trim()===''){out.push('');i++;continue}if(/^<(?:h[1-6]|hr|blockquote|div class="md-table-wrap"|ul class="md-list"|ol class="md-list"|pre class="md-code")/.test(line.trim())||/^@@CODE\d+@@$/.test(line.trim())){out.push(line);i++;continue}out.push('<p>'+line+'</p>');i++}return out.join('\n').replace(/@@CODE(\d+)@@/g,(_,n)=>code[Number(n)]).replace(/\n{2,}/g,'\n')};
const save=()=>{localStorage.setItem(KEY,JSON.stringify(data));clearTimeout(syncTimer);syncTimer=setTimeout(()=>{syncCloud(true)},150);if(data.memoryEnabled!==false&&Array.isArray(data.memory))clearTimeout(window.nexaMemoryTimer),window.nexaMemoryTimer=setTimeout(()=>persistMemory(),180)};
async function syncCloud(silent=false){try{const r=await fetch('/api/sync',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({state:data})});if(r.ok){const j=await r.json().catch(()=>({}));await persistMemory();localStorage.setItem('nexaSchoolLastSync',j.updatedAt||Date.now());if(!silent)showNexaToast(lang==='en'?'Cloud sync completed ✓':'Sincronizzazione cloud completata ✓');return true}if(!silent)showNexaToast(lang==='en'?'Cloud sync failed.':'Sincronizzazione cloud non riuscita.');return false}catch{if(!silent)showNexaToast(lang==='en'?'Cloud sync failed.':'Sincronizzazione cloud non riuscita.');return false}}
async function loadCloud(){try{const r=await fetch('/api/sync');if(r.status===401)return;if(!r.ok)return;const j=await r.json();if(j.state){const c=j.state;data={...data,...c,memory:Array.isArray(c.memory)?c.memory:data.memory,sessions:Array.isArray(c.sessions)?c.sessions:data.sessions,chat:Array.isArray(c.chat)?c.chat:data.chat,profile:{...data.profile,...(c.profile||{})}};saveLocalOnly()}}catch{};await loadMemory()}
const saveLocalOnly=()=>localStorage.setItem(KEY,JSON.stringify(data));
function greet(){const h=new Date().getHours(),g=T[lang].greeting,el=$('#greeting');if(!el)return;const sal=h<12?g[0]:h<18?g[1]:g[2];el.innerHTML='<span class="greeting-text">'+esc(sal)+' 👋</span>'+(data.profile.name?'<span class="greeting-name">'+esc(data.profile.name)+'</span>':'')}
function updateExpiredBadge(){const b=document.querySelector('.nav[data-page="tasks"]');if(!b)return;let d=b.querySelector('.section-dot');if(hasExpiredTasks()){if(!d){d=document.createElement('span');d.className='section-dot';d.setAttribute('aria-label','Compiti scaduti');b.appendChild(d)}}else if(d)d.remove()}function page(p){const enteringMemory=p==='memoryPage'&&window.currentPage!=='memoryPage';const enteringAI=p==='ai'&&window.currentPage!=='ai'&&!window.openingHistoryChat;if(enteringAI&&data.chat.length){const first=data.chat.find(m=>m.role==='user');data.sessions.push({id:Date.now(),title:first?.text||tr('chatPage'),messages:JSON.parse(JSON.stringify(data.chat))});data.chat=[];save()}window.openingHistoryChat=false;window.currentPage=p;document.documentElement.dataset.page=p;document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.page===p));const names={home:tr('home'),subjects:tr('subjects'),tasks:tr('tasks'),calendar:tr('calendar'),study:lang==='en'?'Study Center':'Study Center',scan:tr('scan'),ai:tr('ai'),historyPage:tr('historyTitle'),memoryPage:tr('memory'),docs:tr('docs'),grades:tr('grades'),account:tr('account')};$('#title').textContent=names[p]||tr('home');const f={home,subjects,tasks,calendar,study,scan,ai,historyPage,memoryPage,docs,grades,account,searchPage}[p]||home;updateExpiredBadge();f();if(p==='tasks')markExpiredTasksSeen();if(enteringMemory&&typeof loadMemory==='function')loadMemory().then(()=>{if(window.currentPage==='memoryPage')memoryPage()}).catch(()=>{});document.querySelector('.sidebar').classList.remove('open');applyLanguage();greet();let hb=document.getElementById('globalHomeButton');if(p==='home'){if(hb)hb.remove()}else{if(!hb){hb=document.createElement('button');hb.id='globalHomeButton';hb.className='secondary global-home';hb.type='button';hb.onclick=function(){page('home')};document.body.appendChild(hb)}hb.textContent='⌂ Home'}}
document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>page(b.dataset.page));$('#menu').onclick=()=>document.querySelector('.sidebar').classList.toggle('open');$('#addBtn').onclick=()=>addTask();
function avg(list=data.grades){const nums=(Array.isArray(list)?list:[]).map(g=>Number(g.grade)).filter(Number.isFinite);return nums.length?(nums.reduce((a,b)=>a+b,0)/nums.length).toFixed(2):'—'}
function subjectAverage(subject){return avg(data.grades.filter(g=>String(g.subject).trim().toLowerCase()===String(subject).trim().toLowerCase()))}
function refreshAverages(){document.querySelectorAll('[data-auto-average]').forEach(el=>{const s=el.getAttribute('data-auto-average');el.textContent=subjectAverage(s)});const overall=document.querySelectorAll('[data-auto-overall-average]');overall.forEach(el=>el.textContent=avg())}
function miniChart(list=data.grades,title=''){const g=Array.isArray(list)?list:[];if(!g.length)return '<div class="empty">'+tr('noGradesTrend')+'</div>';const w=760,h=260,p=34,usableW=w-p*2,usableH=h-p*2;const pts=g.map((x,i)=>{const grade=Math.max(0,Math.min(10,Number(x.grade)||0)),xx=g.length===1?w/2:p+(i/(g.length-1))*usableW,yy=h-p-(grade/10)*usableH;return {x:xx,y:yy,g:grade,subject:String(x.subject||''),date:x.date}});const poly=pts.map(q=>q.x+','+q.y).join(' ');return '<div class="grade-chart-card"><div class="grade-chart-title">'+esc(title)+'</div><svg class="grade-chart" viewBox="0 0 '+w+' '+h+'" preserveAspectRatio="none" role="img" aria-label="'+esc(title)+'"><line x1="'+p+'" y1="'+p+'" x2="'+p+'" y2="'+(h-p)+'"/><line x1="'+p+'" y1="'+(h-p)+'" x2="'+(w-p)+'" y2="'+(h-p)+'"/><line x1="'+p+'" y1="'+(h/2)+'" x2="'+(w-p)+'" y2="'+(h/2)+'" class="chart-grid"/><polyline points="'+poly+'" fill="none" class="grade-line"/>'+pts.map((q,i)=>'<circle cx="'+q.x+'" cy="'+q.y+'" r="5" class="grade-point"><title>'+esc(q.subject)+' · '+q.g+'/10</title></circle>').join('')+'<text x="7" y="'+(p+5)+'">10</text><text x="15" y="'+(h/2+5)+'">5</text><text x="20" y="'+(h-p+5)+'">0</text></svg><div class="grade-chart-footer">'+g.length+' '+(g.length===1?'voto':'voti')+' · '+tr('average')+' <b>'+avg(g)+'</b></div></div>'}
function study(){data.study=data.study||{};data.study.objectives=Array.isArray(data.study.objectives)?data.study.objectives:[];data.study.xp=Math.max(0,Number(data.study.xp)||0);data.study.quarterXP=data.study.quarterXP&&typeof data.study.quarterXP==='object'?data.study.quarterXP:{1:0,2:0};data.study.quarterXP[1]=Math.max(0,Number(data.study.quarterXP[1])||0);data.study.quarterXP[2]=Math.max(0,Number(data.study.quarterXP[2])||0);data.study.timerMinutes=Math.max(1,Math.min(180,Number(data.study.timerMinutes)||25));data.study.minutes=Math.max(0,Number(data.study.minutes)||0);const h=Math.floor(data.study.minutes/60),m=data.study.minutes%60;const objectives=data.study.objectives;content.innerHTML='<div class="hero card"><div><div class="eyebrow">NEXA SCHOOL • STUDY CENTER</div><h2>🎯 '+(lang==='en'?'Study smarter with NEXA':'Studia meglio con NEXA')+'</h2><p class="note">'+(lang==='en'?'Set goals, earn XP and focus with your own timer.':'Imposta obiettivi, guadagna XP e studia con il timer che scegli tu.')+'</p></div><div class="metric">'+data.study.xp+' XP</div></div><div class="grid"><div class="card"><div class="small">🏆 XP</div><div class="metric">'+data.study.xp+'</div></div><div class="card"><div class="small">⏱️ '+(lang==='en'?'Study time':'Tempo di studio')+'</div><div class="metric">'+h+'h '+m+'m</div></div><div class="card"><div class="small">🎯 '+(lang==='en'?'Goals':'Obiettivi')+'</div><div class="metric">'+objectives.length+'</div></div></div><div class="two section"><div class="card"><div class="sectionhead"><h3>🎯 '+(lang==='en'?'My goals':'I miei obiettivi')+'</h3><button class="add" onclick="addStudyObjective()">＋ '+(lang==='en'?'Goal':'Obiettivo')+'</button></div><div class="list">'+(objectives.map((o,i)=>'<div class="objective-card"><div><b>'+esc(o.text)+'</b><div class="small">'+(o.status==='reached'?'🏆 '+(lang==='en'?'Reached':'Raggiunto')+(o.xp>0?' · +'+o.xp+' XP':''):'⏳ '+(lang==='en'?'Not decided':'Da completare'))+'</div></div><div class="actions">'+(o.status==='pending'?'<button class="secondary objective-good" onclick="setObjectiveResult('+i+',true)">🏆 '+(lang==='en'?'Reached':'Raggiunto')+' +'+o.xp+' XP</button><button class="secondary objective-bad" onclick="setObjectiveResult('+i+',false)">❌ '+(lang==='en'?'Not reached':'Non raggiunto')+' -'+o.penalty+' XP</button>':'<button class="secondary" disabled>✓ '+(lang==='en'?'Already evaluated':'Già valutato')+'</button>')+'</div></div>').join('')||'<div class="empty">'+(lang==='en'?'Add your first goal.':'Aggiungi il tuo primo obiettivo.')+'</div>')+'</div></div><div class="card"><h3>⏱️ '+(lang==='en'?'Focus session':'Sessione di concentrazione')+'</h3><div id="studyTimer" class="metric">'+String(data.study.timerMinutes).padStart(2,'0')+':00</div><div class="actions"><button class="add" onclick="startStudyTimer()">▶ '+(lang==='en'?'Start':'Avvia')+'</button><button class="secondary" onclick="stopStudyTimer()">■ '+(lang==='en'?'Stop':'Ferma')+'</button><button class="secondary" onclick="customizeStudyTimer()">⚙️ '+(lang==='en'?'Customize':'Personalizza')+'</button></div><p class="note">'+(lang==='en'?'You choose the duration.':'Decidi tu la durata del timer.')+'</p></div></div>'}
function addStudyObjective(){data.study=data.study||{};data.study.objectives=Array.isArray(data.study.objectives)?data.study.objectives:[];const v=prompt(lang==='en'?'What is your goal?':'Qual è il tuo obiettivo?');if(!v||!v.trim())return;let xp=prompt(lang==='en'?'How many XP should this goal give?':'Quanti XP deve dare questo obiettivo?','50');if(xp===null)return;xp=Math.max(1,Math.round(Number(xp)||50));let penalty=prompt(lang==='en'?'How many XP should be removed if not reached?':'Quanti XP togliere se non viene raggiunto?','20');if(penalty===null)return;penalty=Math.max(0,Math.round(Number(penalty)||20));data.study.objectives.push({text:v.trim(),xp,penalty,status:'pending'});save();study()}
function setObjectiveResult(i,reached){const o=data.study?.objectives?.[i];if(!o||o.status!=='pending')return;data.study=data.study||{};data.study.quarterXP=data.study.quarterXP&&typeof data.study.quarterXP==='object'?data.study.quarterXP:{1:0,2:0};const q=data.gradeSettings?.secondActive?2:1;const delta=reached?Number(o.xp)||0:-(Number(o.penalty)||0);data.study.quarterXP[q]=Math.max(0,(Number(data.study.quarterXP[q])||0)+delta);data.study.xp=Math.max(0,(Number(data.study.xp)||0)+delta);o.quarter=q;o.status=reached?'reached':'not-reached';save();showNexaToast(reached?(lang==='en'?'Goal reached! +':'Obiettivo raggiunto! +')+(Number(o.xp)||0)+' XP 🎉':(lang==='en'?'Goal not reached. -':'Obiettivo non raggiunto. -')+(Number(o.penalty)||0)+' XP');study()}
function customizeStudyTimer(){data.study=data.study||{};let v=prompt(lang==='en'?'Timer duration in minutes (1-180):':'Durata del timer in minuti (1-180):',String(data.study.timerMinutes||25));if(v===null)return;v=Math.max(1,Math.min(180,Math.round(Number(v)||25)));data.study.timerMinutes=v;save();study()}
function startStudyTimer(){if(window.nexaStudyTimer)return;const mins=Math.max(1,Math.min(180,Number(data.study?.timerMinutes)||25));let left=mins*60;const el=document.getElementById('studyTimer');if(el)el.textContent=Math.floor(left/60).toString().padStart(2,'0')+':'+(left%60).toString().padStart(2,'0');window.nexaStudyTimer=setInterval(()=>{left--;if(el)el.textContent=Math.floor(left/60).toString().padStart(2,'0')+':'+(left%60).toString().padStart(2,'0');if(left<=0)stopStudyTimer(true)},1000)}
function stopStudyTimer(completed=false){if(window.nexaStudyTimer){clearInterval(window.nexaStudyTimer);window.nexaStudyTimer=null}if(completed){const mins=Math.max(1,Math.min(180,Number(data.study?.timerMinutes)||25));data.study=data.study||{};data.study.minutes=(Number(data.study.minutes)||0)+mins;save();showNexaToast(lang==='en'?'Study session completed! 🎉':'Sessione completata! 🎉');study()}}
function home(){const open=data.tasks.filter(x=>!x.done),today=new Date().toLocaleDateString(lang==='en'?'en-US':'it-IT');content.innerHTML='<div class="hero card"><div><div class="eyebrow">NEXA SCHOOL • '+new Date().toLocaleDateString(lang==='en'?'en-US':'it-IT',{weekday:'long',day:'numeric',month:'long'})+'</div><h2>'+tr('schoolSpace')+'</h2><p class="note">'+tr('organize')+'</p></div><button class="add" onclick="page(\'ai\')">'+tr('askAI')+'</button></div><div class="grid"><div class="card"><div class="small">📚 '+tr('subjects')+'</div><div class="metric">'+data.subjects.length+'</div></div><div class="card"><div class="small">✅ '+tr('openHomework')+'</div><div class="metric">'+open.length+'</div></div><div class="card"><div class="small">📊 '+tr('average')+'</div><div class="metric">'+avg()+'</div></div><div class="card"><div class="small">📁 '+tr('documents')+'</div><div class="metric">'+data.docs.length+'</div></div></div><div class="two section"><div class="card"><div class="sectionhead"><h3>'+tr('upcoming')+'</h3><button class="secondary" onclick="page(\'tasks\')">'+tr('viewAll')+'</button></div><div class="list">'+(open.slice(0,5).map(t=>'<div class="row"><span>☐ '+esc(t.title)+' <span class="tag">'+esc(t.subject)+'</span></span><span class="small">'+esc(t.date||'')+'</span></div>').join('')||'<div class="empty">'+tr('allCaught')+'</div>')+'</div></div><div class="card"><div class="sectionhead"><h3>'+tr('progress')+'</h3><button class="secondary" onclick="page(\'grades\')">'+tr('openGrades')+'</button></div>'+miniChart()+'</div></div>'}
function subjects(){let cards=data.subjects.map((s,i)=>'<div class="card subject-card" onclick="openSubject(\''+encodeURIComponent(s)+'\')"><h3>📚 '+esc(s)+'</h3><div class="grid subject-metrics"><div><div class="small">'+tr('average')+'</div><b>'+subjectAverage(s)+'</b></div><div><div class="small">'+tr('gradesRecorded')+'</div><b>'+data.grades.filter(g=>String(g.subject).trim().toLowerCase()===String(s).trim().toLowerCase()).length+'</b></div><div><div class="small">'+tr('openHomework')+'</div><b>'+data.tasks.filter(t=>String(t.subject).trim().toLowerCase()===String(s).trim().toLowerCase()&&!t.done).length+'</b></div></div><div class="actions" style="margin-top:12px" onclick="event.stopPropagation()"><button class="secondary" onclick="addTask(\''+encodeURIComponent(s)+'\')">'+tr('homeworkAdd')+'</button><button class="secondary" onclick="addGrade(\''+encodeURIComponent(s)+'\')">'+tr('gradeAdd')+'</button><button class="secondary danger" onclick="delSubject('+i+')">'+tr('delete')+'</button></div></div>').join('');content.innerHTML='<div class="card"><div class="sectionhead"><div><h2>'+tr('yourSubjects')+'</h2><p class="note">'+tr('subjectsHint')+'</p></div><button class="add" onclick="addSubject()">'+tr('subjectAdd')+'</button></div><div class="grid">'+(cards||'<div class="empty">'+tr('noSubjects')+'</div>')+'</div></div>'}
function openSubject(subject){const s=decodeURIComponent(subject),grades=data.grades.filter(g=>String(g.subject).trim().toLowerCase()===s.trim().toLowerCase()),tasksFor=data.tasks.filter(t=>String(t.subject).trim().toLowerCase()===s.trim().toLowerCase()),openTasks=tasksFor.filter(t=>!t.done);const gradeRows=grades.map((g,i)=>'<div class="row"><span><b>'+esc(g.grade)+'</b> · '+esc(g.note||tr('grade'))+'</span><button class="secondary danger" onclick="event.stopPropagation();delGrade('+data.grades.indexOf(g)+');openSubject(\''+encodeURIComponent(s)+'\')">×</button></div>').join('');const taskRows=openTasks.map(t=>'<div class="row"><span>☐ '+esc(t.title)+'</span><span class="small">'+esc(t.date||'')+'</span></div>').join('');content.innerHTML='<div class="hero card"><div><div class="eyebrow">NEXA SCHOOL • '+esc(s)+'</div><h2>📚 '+esc(s)+'</h2><p class="note">'+(lang==='en'?'Everything for this subject in one place.':'Tutto quello che riguarda questa materia, in un unico posto.')+'</p></div><button class="secondary" onclick="page(\'subjects\')">← '+tr('subjects')+'</button></div><div class="grid"><div class="card"><div class="small">'+tr('average')+'</div><div class="metric">'+subjectAverage(s)+'</div></div><div class="card"><div class="small">'+tr('gradesRecorded')+'</div><div class="metric">'+grades.length+'</div></div><div class="card"><div class="small">'+tr('openHomework')+'</div><div class="metric">'+openTasks.length+'</div></div></div><div class="two section"><div class="card"><div class="sectionhead"><h3>📊 '+tr('gradeProgress')+'</h3><button class="add" onclick="addGrade(\''+encodeURIComponent(s)+'\')">'+tr('gradeAdd')+'</button></div><div class="list">'+(gradeRows||'<div class="empty">'+tr('addSubjectsGrades')+'</div>')+'</div></div><div class="card"><div class="sectionhead"><h3>✅ '+tr('homeworkAndActivities')+'</h3><button class="add" onclick="addTask(\''+encodeURIComponent(s)+'\')">'+tr('homeworkAdd')+'</button></div><div class="list">'+(taskRows||'<div class="empty">'+tr('noTasks')+'</div>')+'</div></div></div>'}
function addSubject(){const v=prompt(tr('subjectsHint').includes('Aggiungi')?'Nome della materia:':'Subject name:');if(v&&v.trim()&&!data.subjects.includes(v.trim())){data.subjects.push(v.trim());save();subjects()}}
function delSubject(i){if(confirm(lang==='en'?'Delete this subject?':'Eliminare questa materia?')){data.subjects.splice(i,1);save();subjects()}}
function isTaskExpired(t){if(!t||t.done||!t.date)return false;const raw=String(t.date).trim(),m=raw.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})$/);if(!m)return false;const due=new Date(Number(m[3]),Number(m[2])-1,Number(m[1]),23,59,59,999);return Date.now()>due.getTime()}function hasExpiredTasks(){return Array.isArray(data.tasks)&&data.tasks.some(isTaskExpired)}function markExpiredTasksSeen(){let changed=false;(Array.isArray(data.tasks)?data.tasks:[]).forEach(t=>{if(isTaskExpired(t)&&!t.expiredSeen){t.expiredSeen=true;changed=true}});if(changed)save()}function tasks(){const rows=data.tasks.map((t,i)=>{const expired=isTaskExpired(t),unseen=expired&&!t.expiredSeen;return '<div class="row '+(unseen?'task-expired':'')+'"><span><input type="checkbox" '+(t.done?'checked':'')+' onchange="toggleTask('+i+')"> <span class="task-title">'+(unseen?'<span class="status-dot" aria-label="Scaduto"></span>':'')+'<span class="'+(t.done?'done':'')+'">'+esc(t.title)+'</span></span> <span class="tag">'+esc(t.subject)+'</span></span><span class="actions"><span class="small">'+(t.date?tr('due')+': ':'')+esc(t.date||'')+'</span><button class="secondary danger" onclick="delTask('+i+')">'+tr('taskDelete')+'</button></span></div>'}).join('');content.innerHTML='<div class="card"><div class="sectionhead"><div><h2>✅ '+tr('homeworkAndActivities')+'</h2><p class="note">'+tr('tasksHint')+'</p></div><button class="add" onclick="addTask()">'+tr('homeworkAdd')+'</button></div><div class="list">'+(rows||'<div class="empty">'+tr('noTasks')+'</div>')+'</div></div>'}
function addTask(subject=''){subject=subject?decodeURIComponent(subject):'';const title=prompt(lang==='en'?'What do you need to do?':'Cosa devi fare?');if(!title)return;const s=subject||prompt(lang==='en'?'Subject?':'Materia?',data.subjects[0]||'');if(!s)return;const d=prompt(lang==='en'?'Due date? (e.g. 09/02/2026)':'Scadenza? (es. 02/09/2026)','');data.tasks.push({title:title.trim(),subject:s.trim(),date:d,done:false});save();page('tasks')}
function toggleTask(i){data.tasks[i].done=!data.tasks[i].done;save();tasks()}function delTask(i){data.tasks.splice(i,1);save();tasks()}
function showNexaToast(message){let t=document.getElementById('nexaToast');if(!t){t=document.createElement('div');t.id='nexaToast';t.className='nexa-toast';document.body.appendChild(t)}t.textContent=message;t.classList.add('show');clearTimeout(window.nexaToastTimer);window.nexaToastTimer=setTimeout(()=>t.classList.remove('show'),2800)}
function calendar(){const items=[...data.tasks].sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999'));const rows=items.map(t=>'<div class="row"><span>'+((t.done)?'✅':'⏰')+' '+esc(t.title)+' <span class="tag">'+esc(t.subject)+'</span></span><b>'+esc(t.date||tr('noDate'))+'</b></div>').join('');content.innerHTML='<div class="card"><div class="sectionhead"><div><h2>📅 '+tr('schoolCalendar')+'</h2><p class="note">'+tr('calendarHint')+'</p></div><button class="add" onclick="addTask()">'+tr('activityAdd')+'</button></div><div class="list">'+(rows||'<div class="empty">'+tr('emptyCalendar')+'</div>')+'</div></div>'}
function grades(){data.gradeSettings=data.gradeSettings||{secondActive:false};data.study=data.study||{};data.study.quarterXP=data.study.quarterXP&&typeof data.study.quarterXP==='object'?data.study.quarterXP:{1:0,2:0};const first=data.grades.filter(g=>Number(g.quarter)!==2),second=data.grades.filter(g=>Number(g.quarter)===2);const q2=data.gradeSettings.secondActive===true;const comparison='<div class="quarter-comparison card"><div class="sectionhead"><div><h3>⚖️ Confronto quadrimestri</h3><p class="note">Confronta voti, medie e XP tra il 1° e il 2° quadrimestre.</p></div></div><div class="grid"><div class="card"><div class="small">1° quadrimestre</div><div class="metric">'+avg(first)+'</div><div class="small">'+first.length+' voti · '+(Number(data.study.quarterXP[1])||0)+' XP</div></div><div class="card '+(q2?'':'quarter-locked')+'"><div class="small">2° quadrimestre</div><div class="metric">'+avg(second)+'</div><div class="small">'+second.length+' voti · '+(Number(data.study.quarterXP[2])||0)+' XP</div></div></div></div>';const controls='<div class="grade-controls"><button class="add" onclick="addGrade()">'+tr('gradeAdd')+'</button>'+(q2?'<button class="secondary" onclick="setSecondQuarter(false)">⏸️ '+(lang==='en'?'Hide second term':'Disattiva 2° quadrimestre')+'</button>':'<button class="secondary" onclick="setSecondQuarter(true)">▶️ '+(lang==='en'?'Activate second term':'Attiva 2° quadrimestre')+'</button>')+'<button class="secondary danger" onclick="resetGradesAndXP()">🗑️ '+(lang==='en'?'Reset grades, charts, averages & XP':'Reset voti, grafici, medie e XP')+'</button></div>';content.innerHTML='<div class="grades-page"><div class="sectionhead"><div><h2>📈 '+tr('gradeProgress')+'</h2><p class="note">'+(lang==='en'?'All grades are shown in order. The second term stays locked until you activate it.':'Tutti i voti sono mostrati in ordine. Il 2° quadrimestre resta bloccato finché non lo attivi.')+'</p></div>'+controls+'</div><div class="grade-chart-section"><h3>1° quadrimestre</h3>'+miniChart(first,'1° quadrimestre')+'</div>'+(q2?'<div class="grade-chart-section"><h3>2° quadrimestre</h3>'+miniChart(second,'2° quadrimestre')+'</div>':'<div class="card quarter-locked"><b>🔒 2° quadrimestre non attivo</b><p class="note">'+(lang==='en'?'Activate it when your second term begins.':'Attivalo tu quando inizierà il secondo quadrimestre.')+'</p></div>')+comparison+'</div>'}
function setSecondQuarter(active){data.gradeSettings=data.gradeSettings||{};data.gradeSettings.secondActive=!!active;save();grades();showNexaToast(active?(lang==='en'?'Second term activated ▶️':'2° quadrimestre attivato ▶️'):(lang==='en'?'Second term deactivated.':'2° quadrimestre disattivato.'))}function addGrade(subject=''){subject=subject?decodeURIComponent(subject):'';const s=(subject||prompt(lang==='en'?'Subject?':'Materia?',data.subjects[0]||'')||'').trim();if(!s)return;if(!data.subjects.some(x=>String(x).trim().toLowerCase()===s.toLowerCase()))data.subjects.push(s);const g=prompt(lang==='en'?'Grade (0–10, decimals allowed):':'Voto (0–10, anche decimale):');if(g===null||isNaN(g)||Number(g)<0||Number(g)>10)return alert(lang==='en'?'Enter a grade between 0 and 10.':'Inserisci un voto tra 0 e 10.');const n=prompt(lang==='en'?'Description?':'Descrizione?',lang==='en'?'Test':'Verifica');data.gradeSettings=data.gradeSettings||{secondActive:false};data.grades.push({subject:s,grade:Number(g),note:n||tr('grade'),date:new Date().toISOString(),quarter:data.gradeSettings.secondActive?2:1});save();page('grades');setTimeout(refreshAverages,0)}function delGrade(i){data.grades.splice(i,1);save();grades()}function resetGradesAndXP(){if(!confirm(lang==='en'?'Reset ALL grades, charts, averages and XP? This cannot be undone.':'Azzerare TUTTI i voti, grafici, medie e XP? L’operazione non può essere annullata.'))return;data.grades=[];data.gradeSettings={secondActive:false};data.study=data.study||{};data.study.xp=0;data.study.quarterXP={1:0,2:0};data.study.objectives=Array.isArray(data.study.objectives)?data.study.objectives.map(o=>({...o,status:'pending'})):[];save();grades();showNexaToast(lang==='en'?'Grades, charts, averages and XP reset ✓':'Voti, grafici, medie e XP azzerati ✓')}
function scan(){content.innerHTML='<div class="scanbox"><div class="scanicon">📸</div><h2>NEXA Scan</h2><p class="note">'+tr('scanDescription')+'</p><button class="add" onclick="$(\'#fileInput\').click()">'+tr('chooseFile')+'</button><div id="scanresult"></div></div>'}
$('#fileInput').onchange=async e=>{const f=e.target.files&&e.target.files[0];if(!f)return;scanFile=f;const input=e.target;setTimeout(()=>{try{input.value=''}catch{}},0);let text='';const r=$('#scanresult');try{if(f.type==='text/plain')text=await f.text();else if(f.type==='application/pdf'||/\.pdf$/i.test(f.name))text=await extractPdfText(f);else if(f.type==='application/vnd.openxmlformats-officedocument.wordprocessingml.document'||/\.docx$/i.test(f.name))text=await extractDocxText(f)}catch(err){r.innerHTML='<div class="section card"><b>📄 '+esc(f.name)+'</b><p class="note">'+esc(lang==='en'?'The file was acquired, but its text could not be read automatically: ':'File acquisito, ma non è stato possibile leggere automaticamente il testo: ')+(esc(err.message||''))+'</p><button class="secondary" onclick="saveDoc()">'+tr('saveText')+'</button></div>';return}if(f.type.startsWith('image/')){r.innerHTML='<div class="section card"><b>🖼️ '+esc(f.name)+'</b><p class="note">'+tr('acquired')+'</p><div class="actions"><button class="add" onclick="runOCR()">'+tr('ocr')+'</button><button class="secondary" onclick="saveDoc()">'+tr('saveText')+'</button></div></div>'}else{r.innerHTML='<div class="section card"><b>📄 '+esc(f.name)+'</b><p class="note">'+(text?tr('detected')+' '+esc(text.slice(0,1200))+(text.length>1200?'…':''):tr('pdfInfo'))+'</p><div class="actions"><button class="add" onclick="saveDoc()">'+tr('saveText')+'</button>'+(text?'<button class="secondary" onclick="useScanAI()">🤖 NEXA AI</button>':'')+'</div></div>';if(text)scanFile.extracted=text}};
async function runOCR(){if(!scanFile)return;const r=$('#scanresult');r.innerHTML='<div class="section card"><p class="note">'+tr('ocrWorking')+'</p></div>';try{let f=scanFile;try{if(f.size>6*1024*1024)f=await compressImageForOCR(f)}catch{}const fd=new FormData();fd.append('image',f,f.name);fd.append('language',lang);const q=await fetch('/api/scan',{method:'POST',body:fd});const j=await q.json().catch(()=>({}));if(!q.ok)throw new Error(j.error||('OCR HTTP '+q.status));scanFile.extracted=j.text;scanFile.fileUrl=j.fileUrl||'';r.innerHTML='<div class="section card"><b>📝 '+tr('detected')+'</b><p class="scantext">'+esc(j.text).replace(/\n/g,'<br>')+'</p><div class="actions"><button class="add" onclick="saveDoc()">'+tr('saveText')+'</button><button class="secondary" onclick="useScanAI()">🤖 NEXA AI</button></div></div>'}catch(e){r.innerHTML='<div class="section card"><p class="note">'+esc(lang==='en'?'NEXA Scan could not read this image: ':'NEXA Scan non è riuscito a leggere questa immagine: ')+esc(e.message||'Errore')+'</p><button class="secondary" onclick="saveDoc()">'+tr('saveText')+'</button></div>'}}
async function saveDoc(){if(!scanFile)return;const f=scanFile;let text=f.extracted||'';try{if(!text){if(f.type==='text/plain')text=await f.text();else if(f.type==='application/pdf'||/\.pdf$/i.test(f.name))text=await extractPdfText(f);else if(f.type==='application/vnd.openxmlformats-officedocument.wordprocessingml.document'||/\.docx$/i.test(f.name))text=await extractDocxText(f)}const up=await uploadSchoolFile(f);data.docs.push({name:f.name,date:new Date().toLocaleDateString(lang==='en'?'en-US':'it-IT'),text,type:f.type||'',url:up.url||'',key:up.key||'',size:up.size||f.size});save();scanFile=null;page('docs');showNexaToast(lang==='en'?'Document imported successfully ✓':'Documento importato con successo ✓')}catch(e){alert((lang==='en'?'Import failed: ':'Importazione non riuscita: ')+(e.message||'Errore'))}}
function useScanAI(){const text=scanFile?.extracted||'';if(!text)return;data.pendingAI=text;save();page('ai')}
function docs(){const rows=data.docs.map((d,i)=>'<div class="row"><span>📄 <b>'+esc(d.name)+'</b> <span class="small">'+esc(d.date)+'</span></span><span class="actions">'+(d.url?'<button class="secondary" onclick="window.open(\''+esc(d.url)+'\',\'_blank\')">↗️ Apri</button>':'')+(d.text?'<button class="secondary" onclick="useDocAI('+i+')">🤖 AI</button>':'')+'<button class="secondary danger" onclick="delDoc('+i+')">'+tr('delete')+'</button></span></div>').join('');content.innerHTML='<div class="card"><div class="sectionhead"><div><h2>📁 '+tr('documents')+'</h2><p class="note">'+tr('docsHint')+'</p></div><button class="add" onclick="$(\'#fileInput\').click()">'+tr('import')+'</button></div><div class="list">'+(rows||'<div class="empty">'+tr('noDocs')+'</div>')+'</div></div>'}function useDocAI(i){data.pendingAI=data.docs[i]?.text||'';save();page('ai')}function delDoc(i){data.docs.splice(i,1);save();docs()}
function historyPage(){const sessions=[...(data.sessions||[])];if(data.chat.length)sessions.push({id:'current',title:data.chat.find(m=>m.role==='user')?.text||tr('chatPage'),messages:data.chat,current:true});const rows=sessions.slice().reverse().map((s,i)=>'<div class="history-card"><div><h3>💬 '+esc(s.title||tr('chatPage'))+'</h3><div class="small">'+(s.messages?.length||0)+' messaggi</div></div><div class="actions">'+(s.current?'<button class="secondary" onclick="page(\'ai\')">'+tr('openChat')+'</button>':'<button class="secondary" onclick="openHistoryChat('+i+')">'+tr('openChat')+'</button>')+(s.current?'<button class="secondary danger" onclick="deleteCurrentChat()">'+tr('deleteHistoryItem')+'</button>':'<button class="secondary danger" onclick="deleteHistory('+i+')">'+tr('deleteHistoryItem')+'</button>')+'</div></div>').join('');content.innerHTML='<div class="card page-card"><div class="sectionhead"><div><h2>'+tr('historyTitle')+'</h2><p class="note">'+tr('historyDescription')+'</p></div><div class="actions"><button class="add" onclick="page(\'ai\')">'+tr('chatPage')+'</button><button class="secondary danger" onclick="clearAllHistory()">'+(lang==='en'?'🗑️ Delete all':'🗑️ Elimina tutto')+'</button></div></div><div class="history-list-page">'+(rows||'<div class="empty">'+tr('noHistory')+'</div>')+'</div></div>'}
function openHistoryChat(i){const sessions=[...(data.sessions||[])];const s=sessions.slice().reverse()[i];if(!s)return;data.chat=Array.isArray(s.messages)?JSON.parse(JSON.stringify(s.messages)):[];save();window.openingHistoryChat=true;page('ai')}
function deleteHistory(i){const sessions=[...(data.sessions||[])];const idx=sessions.length-1-i;if(idx<0)return;if(confirm(lang==='en'?'Delete this conversation?':'Eliminare questa conversazione?')){sessions.splice(idx,1);data.sessions=sessions;save();historyPage()}} function deleteCurrentChat(){if(!data.chat.length)return;if(confirm(lang==='en'?'Delete the current conversation?':'Eliminare la conversazione attuale?')){data.chat=[];save();historyPage()}} function clearAllHistory(){if(confirm(lang==='en'?'Delete ALL NEXA AI conversations?':'Eliminare TUTTE le conversazioni di NEXA AI?')){data.sessions=[];data.chat=[];save();historyPage()}}
function memoryPage(){const rows=data.memory.map((m,i)=>'<div class="memory-item"><span>🧠 '+esc(m)+'</span><button class="secondary danger" onclick="deleteMemory('+i+')">'+tr('deleteMemory')+'</button></div>').join('');content.innerHTML='<div class="card page-card"><div class="sectionhead"><div><h2>'+tr('memoryTitle')+'</h2><p class="note">'+tr('memoryDescription')+'</p></div><div class="actions"><button class="add" onclick="addMemory()">'+tr('addMemory')+'</button><button class="secondary danger" onclick="clearAllMemory()">'+(lang==='en'?'🗑️ Delete all':'🗑️ Elimina tutto')+'</button></div></div><label class="memory-toggle"><input type="checkbox" '+(data.memoryEnabled?'checked':'')+' onchange="data.memoryEnabled=this.checked;save();memoryPage()"> <b>'+tr('memoryEnabled')+'</b></label><p class="note">'+(data.memoryEnabled?tr('memoryOn'):tr('memoryOff'))+'</p><div class="memory-list">'+(rows||'<div class="empty">'+tr('noMemory')+'</div>')+'</div></div>'}
async function persistMemory(){try{const r=await fetch('/api/memory',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({memories:data.memory,enabled:data.memoryEnabled!==false})});if(!r.ok)throw new Error('HTTP '+r.status);return true}catch(e){console.warn('Memory sync failed',e);return false}}
async function loadMemory(){try{const r=await fetch('/api/memory');if(r.status===401)return;if(!r.ok)return;const j=await r.json();data.memory=Array.isArray(j.memories)?j.memories:data.memory;data.memoryEnabled=j.enabled!==false;saveLocalOnly()}catch(e){console.warn('Memory load failed',e)}}
async function addMemory(){const v=prompt(tr('memoryPlaceholder'));if(v&&v.trim()){data.memory.push(v.trim());saveLocalOnly();const ok=await persistMemory();if(!ok)alert(lang==='en'?'Memory could not be saved to your account.':'Il ricordo non è stato salvato sul tuo account.');memoryPage()}}
async function clearAllMemory(){if(!data.memory.length)return;if(confirm(lang==='en'?'Delete all saved memories?':'Eliminare tutti i ricordi salvati?')){data.memory=[];saveLocalOnly();const ok=await persistMemory();memoryPage();if(!ok)alert(lang==='en'?'Memory could not be saved to your account.':'La memoria non è riuscita a salvarsi sul tuo account.')}}
async function deleteMemory(i){data.memory.splice(i,1);saveLocalOnly();const ok=await persistMemory();memoryPage();if(!ok)alert(lang==='en'?'Memory could not be saved to your account.':'La memoria non è riuscita a salvarsi sul tuo account.')}
function ai(){const pending=data.pendingAI||'';delete data.pendingAI;const bubbles=data.chat.map(m=>'<div class="bubble '+(m.role==='user'?'me':'')+'"><div class="bubble-role">'+(m.role==='user'?tr('you'):'NEXA AI')+'</div><div>'+(m.role==='assistant'?aiFormat(m.text):esc(m.text).replace(/\n/g,'<br>'))+'</div>'+(m.attachment?renderAIAttachment(m.attachment):'')+(m.role==='assistant'?'<button class="pdfbtn" onclick="downloadPDFText(decodeURIComponent(this.dataset.pdf))" data-pdf="'+encodeURIComponent(m.text)+'">📄 '+tr('downloadPDF')+'</button>':'')+'</div>').join('');const hist=data.chat.map((m,i)=>'<button class="history-item" onclick="jumpToMessage('+i+')"><b>'+(m.role==='user'?tr('you'):'NEXA AI')+'</b><span>'+esc(m.text.slice(0,100))+(m.text.length>100?'…':'')+'</span></button>').join('');content.innerHTML='<div class="card ai-card"><div class="sectionhead"><div><h2>🤖 NEXA AI</h2><p class="note">'+tr('aiDescription')+'</p></div><div class="actions"><button class="secondary" onclick="page(\'historyPage\')">'+tr('history')+'</button><button class="secondary" onclick="page(\'memoryPage\')">🧠 '+tr('memory')+'</button><button class="secondary" onclick="newChat()">'+tr('newChat')+'</button><button class="secondary danger" onclick="clearChat()">'+tr('clear')+'</button></div></div><div id="chat" class="chat">'+(bubbles||'<div class="ai-welcome"><div class="ai-orb">✦</div><h3>'+(data.profile.name?(lang==='en'?'Hi '+esc(data.profile.name)+'! I’m NEXA AI 👋':'Ciao '+esc(data.profile.name)+'! Sono NEXA AI 👋'):tr('welcome'))+'</h3><p class="note">'+tr('welcomeText')+'</p></div>')+'</div><div class="quick"><button class="secondary" onclick="quickAI(0)">🧠 '+tr('summarize')+'</button><button class="secondary" onclick="quickAI(1)">❓ '+tr('createQuiz')+'</button><button class="secondary" onclick="quickAI(2)">🎓 '+tr('explain')+'</button><button class="secondary" onclick="quickAI(3)">📝 '+tr('studySheet')+'</button></div><div class="attachbar"><span class="ai-upload-hint">📎</span><button class="secondary" onclick="document.getElementById(\'docInput\').click()">'+tr('upload')+'</button><button class="secondary" onclick="document.getElementById(\'cameraInput\').click()">'+tr('camera')+'</button></div><div class="chatbar"><textarea id="prompt" rows="1" placeholder="'+tr('write')+'" oninput="autoResizePrompt()" onkeydown="if(event.key===\'Enter\'&&!event.shiftKey){event.preventDefault();sendAI()}">'+esc(pending)+'</textarea><button class="sendbtn" aria-label="'+tr('sendMessage')+'" title="'+tr('sendMessage')+'" onclick="sendAI()">➤</button></div><div id="thinking" class="thinking" hidden>'+tr('thinking')+'</div></div><input id="docInput" type="file" accept=".pdf,.txt,.doc,.docx,image/*" hidden onchange="handleAIFile(this.files[0])"><input id="cameraInput" type="file" accept="image/*" capture="environment" hidden onchange="handleAIFile(this.files[0])">';setTimeout(()=>{autoResizePrompt();$('#chat')?.scrollTo(0,99999)},0)}
function toggleHistory(){const x=$('#chatHistory');if(x)x.hidden=!x.hidden}
function jumpToMessage(i){const el=$('#chat')?.children[i];if(el)el.scrollIntoView({behavior:'smooth',block:'center'})}
async function uploadSchoolFile(f){const fd=new FormData();fd.append('file',f,f.name);fd.append('language',lang);const r=await fetch('/api/upload',{method:'POST',body:fd});const j=await r.json();if(!r.ok)throw new Error(j.error||'Upload error');return j}
async function compressImageForOCR(f){return new Promise((resolve,reject)=>{const img=new Image(),url=URL.createObjectURL(f);img.onload=()=>{try{const max=1800,scale=Math.min(1,max/Math.max(img.naturalWidth,img.naturalHeight));const c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.naturalWidth*scale));c.height=Math.max(1,Math.round(img.naturalHeight*scale));c.getContext('2d').drawImage(img,0,0,c.width,c.height);c.toBlob(b=>{URL.revokeObjectURL(url);if(!b)return reject(new Error('Impossibile preparare l’immagine'));resolve(new File([b],'nexa-ocr.jpg',{type:'image/jpeg'}))},'image/jpeg',.78)}catch(e){URL.revokeObjectURL(url);reject(e)}};img.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('Immagine non valida'))};img.src=url})}
async function extractPdfText(f){if(!window.pdfjsLib){await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='/pdfjs.min.js';s.onload=resolve;s.onerror=()=>reject(new Error('Lettore PDF non disponibile'));document.head.appendChild(s)})}window.pdfjsLib.GlobalWorkerOptions.workerSrc='/pdfjs.worker.min.js';const pdf=await window.pdfjsLib.getDocument({data:await f.arrayBuffer(),useWorkerFetch:true,isEvalSupported:true}).promise;let out=[];for(let i=1;i<=pdf.numPages;i++){const p=await pdf.getPage(i),c=await p.getTextContent({normalizeWhitespace:true});out.push(c.items.map(x=>x.str||'').join(' '))}return out.join('\n\n').trim()}
async function extractDocxText(f){if(!window.mammoth){await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='/mammoth.browser.min.js';s.onload=resolve;s.onerror=()=>reject(new Error('Lettore DOCX non disponibile'));document.head.appendChild(s)})}const r=await window.mammoth.extractRawText({arrayBuffer:await f.arrayBuffer()});return String(r.value||'').trim()}
function renderAIPendingAttachment(){const bar=document.querySelector('.attachbar');if(!bar)return;let box=document.getElementById('aiPendingAttachment');if(!box){box=document.createElement('div');box.id='aiPendingAttachment';box.className='ai-pending';bar.appendChild(box)}const a=data.pendingAttachment;if(!a){box.innerHTML='';box.style.display='none';return}box.style.display='flex';box.innerHTML=(String(a.type||'').startsWith('image/')&&a.previewUrl?'<img src="'+esc(a.previewUrl)+'" alt="'+esc(a.name)+'"><span>🖼️ '+esc(a.name)+'</span>':'<span>📎 '+esc(a.name)+'</span>')+'<button onclick="data.pendingAttachment=null;renderAIPendingAttachment()" title="Rimuovi allegato">✕</button>'}async function handleAIFile(f){if(!f)return;try{const up=await uploadSchoolFile(f);const base={name:f.name,date:new Date().toLocaleDateString(lang==='en'?'en-US':'it-IT'),type:f.type||'',url:up.url||'',key:up.key||'',size:up.size||f.size};data.pendingAttachment={name:base.name,type:base.type,url:base.url,key:base.key,previewUrl:f.type.startsWith('image/')?URL.createObjectURL(f):'',text:''};window.nexaPendingFile=f;data.docs.push(base);save();renderAIPendingAttachment();$('#prompt').focus()}catch(e){alert((lang==='en'?'Upload failed: ':'Caricamento non riuscito: ')+(e.message||'Errore'))}finally{document.querySelectorAll('#docInput,#cameraInput').forEach(x=>x.value='')}}
function newChat(){if(!data.chat.length){ai();return}if(confirm(tr('newChatConfirm'))){const first=data.chat.find(m=>m.role==='user');data.sessions.push({id:Date.now(),title:first?.text||tr('chatPage'),messages:JSON.parse(JSON.stringify(data.chat))});data.chat=[];save();ai()}}
function quickAI(i){const a=lang==='en'?['Summarize this topic simply and with key points: ','Ask me 5 questions to review this topic and then correct me: ','Explain this topic step by step, like I’m a high-school student: ','Create a study sheet with definitions, key concepts and examples: ']:['Riassumi questo argomento in modo semplice e con punti chiave: ','Fammi 5 domande per ripassare questo argomento e poi correggimi: ','Spiegami questo argomento passo per passo, come a uno studente delle superiori: ','Crea una scheda di studio con definizioni, concetti chiave ed esempi: '];$('#prompt').value=a[i];$('#prompt').focus()}
function renderAIAttachment(a){if(!a)return '';const type=String(a.type||'');if(type.startsWith('image/')&&(a.previewUrl||a.url))return '<div class="ai-attachment ai-image"><img src="'+esc(a.previewUrl||a.url)+'" alt="'+esc(a.name||'Immagine')+'" loading="eager" onclick="window.open(this.src,\'_blank\')"><div>🖼️ '+esc(a.name||'Immagine')+'</div></div>';return '<div class="ai-attachment">📎 <b>'+esc(a.name||'Documento')+'</b><span>'+(a.text?' ✓ Letto':'')+'</span></div>'}function autoResizePrompt(){const el=$('#prompt');if(!el)return;el.style.height='auto';const max=Math.min(130,Math.max(70,Math.floor(window.innerHeight*.22)));el.style.height=Math.min(el.scrollHeight,max)+'px';el.style.overflowY=el.scrollHeight>max?'auto':'hidden'}function autoRemember(text){if(!data.memoryEnabled||!text)return;const s=String(text).trim(),facts=[];let m=s.match(/\b(?:mi chiamo|chiamami)\s+([A-Za-zÀ-ÖØ-öø-ÿ' -]{2,60})/i);if(m)facts.push('Il nome dell’utente è '+m[1].trim().replace(/[.!?,;:]+$/,''));m=s.match(/\b(?:mi piace|adoro|preferisco|non mi piace)\s+(.{2,100})/i);if(m)facts.push('Preferenza dell’utente: '+m[0].trim().replace(/[.!?]+$/,''));m=s.match(/\b(?:preferisco spiegazioni|imparo meglio|mi aiuta)\s+(.{2,100})/i);if(m)facts.push('Metodo di studio preferito: '+m[0].trim().replace(/[.!?]+$/,''));m=s.match(/\b(?:studio|sto studiando)\s+(.{2,100})/i);if(m&&/(?:matematica|italiano|inglese|storia|scienze|fisica|chimica|geografia|latino|informatica|arte|tecnologia)/i.test(m[1]))facts.push('Materia/argomento di studio: '+m[1].trim().replace(/[.!?]+$/,''));for(const fact of facts){if(fact&&!data.memory.includes(fact))data.memory.push(fact)}if(facts.length){if(data.memory.length>50)data.memory=data.memory.slice(-50);save();void persistMemory()}}async function sendAI(){const input=$('#prompt');if(!input)return;const p=input.value.trim();const attachment=data.pendingAttachment||null;if(!p&&!attachment)return;autoRemember(p);const memMatch=p.match(/^(?:ricorda(?:ti)?|ricordati|ricorda che|tieni a mente|salva(?:lo)? in memoria|remember|remember that)\s*[:,-]?\s*(.+)$/i);if(memMatch&&data.memoryEnabled){const fact=memMatch[1].trim().replace(/^che\s+/i,'');if(fact&&!data.memory.includes(fact)){data.memory.push(fact);save();void persistMemory();}}const file=window.nexaPendingFile||null;let attachmentForAI=attachment?{name:attachment.name,type:attachment.type,url:attachment.url,previewUrl:attachment.previewUrl,text:''}:null;try{if(file&&attachmentForAI&&!String(file.type||'').startsWith('image/')){if(file.type==='text/plain'){attachmentForAI.text=(await file.text()).slice(0,30000)}else if(file.type==='application/pdf'||/\.pdf$/i.test(file.name)){attachmentForAI.text=(await extractPdfText(file)).slice(0,30000)}else if(file.type==='application/vnd.openxmlformats-officedocument.wordprocessingml.document'||/\.docx$/i.test(file.name)){attachmentForAI.text=(await extractDocxText(file)).slice(0,30000)}}}catch(e){alert((lang==='en'?'I could not read this document: ':'Non riesco a leggere questo documento: ')+(e.message||'Errore'));return}data.pendingAttachment=null;window.nexaPendingFile=null;input.value='';autoResizePrompt();data.chat.push({role:'user',text:p||('📎 '+(attachment?.name||'Allegato')),at:Date.now(),attachment:attachmentForAI});save();renderAIPendingAttachment();const t=$('#thinking');if(t)t.hidden=false;try{const r=await fetch('/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt:p,language:lang,displayName:data.profile.name||'',memoryEnabled:!!data.memoryEnabled,memory:data.memory||[],history:data.chat.slice(-13,-1).map(m=>({role:m.role,content:m.text})),attachment:attachmentForAI})});const j=await r.json();if(r.status===401){location.href='/login?next=/';return}if(!r.ok)throw new Error(j.error||'Server error');data.chat.push({role:'assistant',text:j.text||'No response.'})}catch(e){data.chat.push({role:'assistant',text:(lang==='en'?'I can’t connect to NEXA AI right now. ':'Non riesco a collegarmi a NEXA AI in questo momento. ')+(e.message||'')})}save();ai()}
async function downloadPDFText(text){try{const r=await fetch('/api/pdf',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:'NEXA School',text})});if(!r.ok)throw new Error('PDF '+r.status);const blob=await r.blob();if(!blob.size)throw new Error('PDF vuoto');const url=URL.createObjectURL(new Blob([blob],{type:'application/pdf'}));const a=document.createElement('a');a.href=url;a.download='NEXA-School.pdf';a.target='_blank';a.rel='noopener';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}catch(e){alert(lang==='it'?'Non riesco a creare il PDF in questo momento. Riprova.':'I cannot create the PDF right now. Please try again.')}}
function clearChat(){if(confirm(lang==='it'?'Cancellare tutta la cronologia di NEXA AI?':'Clear all NEXA AI chat history?')){data.chat=[];save();ai()}}
async function account(){let s=null;try{s=await window.hatchable?.auth?.getSession()}catch{}const u=s?.user;content.innerHTML='<div class="card account"><div class="account-avatar">'+esc((u?.name||data.profile.name||'N').slice(0,1).toUpperCase())+'</div><h2>'+tr('accountTitle')+'</h2><p class="note">'+(u?tr('signedIn')+' '+esc(u.email||u.name||'account'):tr('noAccount'))+'</p><div class="form"><label>'+tr('displayName')+'<input id="displayName" value="'+esc(data.profile.name)+'" placeholder="'+tr('namePlaceholder')+'"></label><button class="add" onclick="saveProfile()">'+tr('save')+'</button>'+(u?'<button class="secondary danger" onclick="signOut()">'+tr('logout')+'</button>':'<button class="secondary" onclick="location.href=\'/login?next=/\'">'+tr('login')+'</button>')+'</div></div><div class="section card"><h3>'+tr('localMemory')+'</h3><p class="note">'+tr('memoryText')+'</p><div class="actions"><button class="secondary" onclick="syncCloud()">'+tr('saveCloud')+'</button><button class="secondary danger" onclick="resetAll()">'+tr('deleteAll')+'</button></div></div>'}
function saveProfile(){data.profile.name=$('#displayName').value.trim();save();greet();showNexaToast(lang==='en'?'Saved successfully ✓':'Salvato con successo ✓');account()}async function signOut(){await window.hatchable.auth.signOut();account()}function resetAll(){if(confirm(lang==='en'?'Do you really want to delete all local NEXA School data?':'Vuoi davvero cancellare tutti i dati locali di NEXA School?')){localStorage.removeItem(KEY);location.reload()}}
function searchPage(){const render=()=>{const q=(window.searchQuery||'').trim().toLowerCase();const found=[];if(q){data.subjects.filter(x=>x.toLowerCase().includes(q)).forEach(x=>found.push('📚 '+esc(x)));data.tasks.filter(x=>(x.title+' '+x.subject).toLowerCase().includes(q)).forEach(x=>found.push('✅ '+esc(x.title)+' · '+esc(x.subject)));data.docs.filter(x=>x.name.toLowerCase().includes(q)||(x.text||'').toLowerCase().includes(q)).forEach(x=>found.push('📄 '+esc(x.name)));data.grades.filter(x=>x.subject.toLowerCase().includes(q)||(x.note||'').toLowerCase().includes(q)).forEach(x=>found.push('📊 '+esc(x.subject)+' · '+esc(x.grade)));}const box=$('#searchResults');if(box)box.innerHTML=found.length?found.map(x=>'<div class="row">'+x+'</div>').join(''):(q?'<div class="empty">'+tr('noResults')+'</div>':'<div class="empty">'+tr('search')+'</div>')};content.innerHTML='<div class="card"><h2>'+tr('searchTitle')+'</h2><div class="searchbox"><input id="globalSearch" value="'+esc(window.searchQuery||'')+'" placeholder="'+tr('search')+'" autocomplete="off"></div><div id="searchResults" class="list" style="margin-top:14px"></div></div>';const input=$('#globalSearch');if(input){input.addEventListener('input',()=>{window.searchQuery=input.value;render()});input.addEventListener('keydown',e=>{e.stopPropagation()})}render();setTimeout(()=>input?.focus(),0)}
function applyLanguage(){document.documentElement.lang=lang;document.querySelectorAll('.nav').forEach(b=>{const s=b.querySelector('span');if(s)s.textContent=tr(b.dataset.page)});const n=$('#addBtn');if(n)n.textContent=tr('add');const l=$('#languageSelect');if(l){l.value=lang;l.setAttribute('aria-label',tr('language'))}const f=document.querySelector('.sidefoot');if(f)f.textContent='NEXA School • 2026';const s=$('#globalSearch');if(s)s.placeholder=tr('search')}
function setLanguage(v){lang=v==='en'?'en':'it';localStorage.setItem(LANG_KEY,lang);page(window.currentPage||'home')}
loadCloud().finally(async()=>{await loadMemory();greet();page('home');clearInterval(window.nexaExpiredBadgeTimer);window.nexaExpiredBadgeTimer=setInterval(updateExpiredBadge,60000);});